57:     @Transactional
58:     public Map<String, Object> quote(String creditId, String productId, BigDecimal amount, Integer termMonths,
59:                                      String repaymentMode, String firstRepaymentDate) {
60:         ProductConfig product = product(productId);
61:         validateAmountAndTerm(product, amount, termMonths, repaymentMode);
62:         limitService.get(creditId); // 授信存在性
63:         Map<String, Object> trial = fineract.calculateLoanSchedule(product.getFineractProductId(),
64:                 amount, termMonths, repaymentMode, firstRepaymentDate);
65: 
66:         DrawdownQuote quote = new DrawdownQuote();
67:         quote.setQuoteNo(Ids.next("QT-"));
68:         quote.setCreditId(creditId);
