72:         quote.setRepaymentMode(repaymentMode);
73:         quote.setFirstRepaymentDate(firstRepaymentDate);
74:         quote.setAnnualInterestRate(product.getAnnualInterestRate());
75:         quote.setValidUntil(Ids.now().plusMinutes(30));
76:         quote.setStatus(DrawdownQuote.Status.UNUSED);
77:         quote.setTrialScheduleJson(writeJson(trial));
78:         quote.setProductVersionId(resolveVersion(product).getVersionId());
79:         quoteRepo.save(quote);
80:         return Map.of("quoteNo", quote.getQuoteNo(),
81:                 "productVersionId", quote.getProductVersionId(),
82:                 "annualInterestRate", product.getAnnualInterestRate(),
83:                 "trialSchedule", trial.get("periods") == null ? List.of() : trial.get("periods"),
