89:      */
90:     private ProductConfigVersion resolveVersion(ProductConfig product) {
91:         Optional<ProductConfigVersion> latest = versionRepo.findFirstByProductIdOrderByVersionDesc(product.getProductId());
92:         if (latest.isPresent() && sameRules(latest.get(), product)) {
93:             return latest.get();
94:         }
95:         ProductConfigVersion version = new ProductConfigVersion();
96:         version.setVersionId("PV-" + product.getProductId() + "-"
97:                 + (latest.map(v -> v.getVersion() + 1).orElse(1)));
98:         version.setProductId(product.getProductId());
99:         version.setVersion(latest.map(v -> v.getVersion() + 1).orElse(1));
100:         version.setMinAmount(product.getMinAmount());
101:         version.setMaxAmount(product.getMaxAmount());
102:         version.setTerms(product.getTerms());
103:         version.setRepaymentModes(product.getRepaymentModes());
104:         version.setAnnualInterestRate(product.getAnnualInterestRate());
105:         version.setRequiresGuarantee(product.isRequiresGuarantee());
106:         version.setFineractProductId(product.getFineractProductId());
107:         version.setEffectiveAt(Ids.now());
108:         return versionRepo.save(version);
109:     }
