111:     private boolean sameRules(ProductConfigVersion version, ProductConfig product) {
112:         return version.getMinAmount().compareTo(product.getMinAmount()) == 0
113:                 && version.getMaxAmount().compareTo(product.getMaxAmount()) == 0
114:                 && version.getTerms().equals(product.getTerms())
115:                 && version.getRepaymentModes().equals(product.getRepaymentModes())
116:                 && version.getAnnualInterestRate().compareTo(product.getAnnualInterestRate()) == 0
