272:     private void validateAmountAndTerm(ProductConfigVersion version, BigDecimal amount, Integer termMonths, String repaymentMode) {
273:         if (amount.compareTo(version.getMinAmount()) < 0 || amount.compareTo(version.getMaxAmount()) > 0) {
274:             throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
275:         }
276:         if (!version.termList().contains(termMonths)) {
277:             throw new BizException(BizException.Code.TERM_NOT_SUPPORTED);
278:         }
279:         if (!version.repaymentModeList().contains(repaymentMode)) {
280:             throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
281:         }
282:     }
283: 
284:     private ProductConfig product(String productId) {
285:         return productRepo.findById(productId).orElseThrow(() -> new BizException(BizException.Code.PRODUCT_NOT_OPEN));
286:     }
